import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import ts from 'typescript';
const source = await readFile(new URL('../src/translationPlan.ts', import.meta.url), 'utf8');
const js = ts.transpileModule(source, { compilerOptions: { module: ts.ModuleKind.ESNext, target: ts.ScriptTarget.ES2022 } }).outputText;
const { translationPlan } = await import('data:text/javascript;base64,' + Buffer.from(js).toString('base64'));
const pack = (from, to, installed = false) => ({ id: `${from}_${to}`, source: from, target: to, label: `${from} → ${to}`, installed });
const packs = [pack('en', 'vi'), pack('vi', 'en'), pack('ja', 'en'), pack('en', 'ja'), pack('zh', 'en')];
const ids = plan => plan.required.map(p => p.id);
assert.deepEqual(ids(translationPlan(packs, 'en', 'vi')), ['en_vi']);
assert.deepEqual(ids(translationPlan(packs, 'vi', 'en')), ['vi_en']);
assert.deepEqual(ids(translationPlan(packs, 'ja', 'vi')), ['ja_en', 'en_vi']);
assert.equal(translationPlan(packs, 'ja', 'vi').kind, 'bridge');
assert.deepEqual(ids(translationPlan(packs, 'auto', 'vi')), ['en_vi']);
assert.deepEqual(ids(translationPlan(packs, 'auto', 'en')), []);
assert.equal(translationPlan(packs, 'vi', 'vi').kind, 'identity');
assert.deepEqual(ids(translationPlan(packs, 'vi', 'vi')), []);
assert.equal(translationPlan(packs, 'xx', 'vi').kind, 'unavailable');
assert.deepEqual(ids(translationPlan(packs, 'zh-CN', 'en')), ['zh_en']);
assert.deepEqual(ids(translationPlan([...packs, pack('ja', 'vi')], 'ja', 'vi')), ['ja_vi']);
const bridgeInstalled = [pack('ja', 'en', true), pack('en', 'vi', true), pack('ja', 'vi')];
assert.deepEqual(ids(translationPlan(bridgeInstalled, 'ja', 'vi')), ['ja_en', 'en_vi']);
assert.equal(translationPlan(bridgeInstalled, 'ja', 'vi').required.filter(p => !p.installed).length, 0);
const partial = [pack('ja', 'en', true), pack('en', 'vi')];
assert.deepEqual(translationPlan(partial, 'ja', 'vi').required.filter(p => !p.installed).map(p => p.id), ['en_vi']);
assert.deepEqual(ids(translationPlan([pack('ja', 'en', true)], 'auto', 'en')), ['ja_en']);
console.log('15 translation installation-plan assertions passed.');
